using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

// Set up options with default reflection-based metadata
var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver(),
    WriteIndented    = true
};

// ── 1. Strongly-typed metadata retrieval ─────────────────────────
// GetTypeInfo<T>() returns JsonTypeInfo<T> directly — no cast needed.
JsonTypeInfo<Person> personInfo = (JsonTypeInfo<Person>)options.GetTypeInfo(typeof(Person));
Console.WriteLine($"Type handled : {personInfo.Type.Name}");
Console.WriteLine($"Kind         : {personInfo.Kind}");
Console.WriteLine($"Properties   : {string.Join(", ", personInfo.Properties.Select(p => p.Name))}");
Console.WriteLine();

// Round-trip to prove the metadata works
var json   = JsonSerializer.Serialize(new Person("Ada", 36), personInfo);
var person = JsonSerializer.Deserialize(json, personInfo)!;
Console.WriteLine($"Serialized   : {json}");
Console.WriteLine($"Deserialized : {person}");
Console.WriteLine();

// ── 2. Probe without throwing ────────────────────────────────────
// TryGetTypeInfo returns false instead of throwing when metadata
// is unavailable (e.g. the resolver doesn't cover the type).
var limited = new JsonSerializerOptions
{
    // A resolver that knows about Person only
    TypeInfoResolver = new DefaultJsonTypeInfoResolver
    {
        Modifiers =
        {
            info =>
            {
                if (info.Type != typeof(Person))
                    throw new NotSupportedException($"Unsupported: {info.Type}");
            }
        }
    }
};

bool hasPerson  = limited.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? pInfo);
bool hasUnknown = limited.TryGetTypeInfo(typeof(UnknownWidget), out JsonTypeInfo? wInfo);

Console.WriteLine($"Has Person?        {hasPerson}  (info is null: {pInfo is null})");
Console.WriteLine($"Has UnknownWidget? {hasUnknown}  (info is null: {wInfo is null})");

